<?php require_once __DIR__.'/_layout.php'; $pdo=db(); $id=(int)($_GET['id']??0); if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],$id]);header('Location: order-detail.php?id='.$id.'&ok=Đã cập nhật');exit;} $q=$pdo->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$id]);$o=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC); admin_header('Chi tiết đơn hàng','orders'); admin_flash(); ?>
<div class="admin-card"><div class="card-head"><div><p><?=htmlspecialchars($o['order_code'])?></p><h2><?=htmlspecialchars($o['customer_name'])?></h2></div></div><p><b>Điện thoại:</b> <?=htmlspecialchars($o['phone'])?> · <b>Địa chỉ:</b> <?=htmlspecialchars($o['address'])?>, <?=htmlspecialchars($o['district'])?>, <?=htmlspecialchars($o['city'])?></p><table><thead><tr><th>Sản phẩm</th><th>Tuỳ chọn</th><th>SL</th><th>Giá</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=htmlspecialchars($i['product_name'])?></td><td><?=htmlspecialchars($i['option_text'])?></td><td><?=$i['quantity']?></td><td><?=number_format($i['unit_price']*$i['quantity'],0,',','.')?>đ</td></tr><?php endforeach; ?></tbody></table><h2 style="margin-top:24px">Tổng: <?=number_format($o['subtotal'],0,',','.')?>đ</h2><form method="post" class="admin-form"><label>Trạng thái<select name="status"><?php foreach(['new'=>'Mới','confirmed'=>'Đã xác nhận','shipping'=>'Đang giao','completed'=>'Hoàn tất','cancelled'=>'Đã huỷ'] as $v=>$l): ?><option value="<?=$v?>" <?=$o['status']===$v?'selected':''?>><?=$l?></option><?php endforeach; ?></select></label><button class="admin-btn" type="submit">Cập nhật trạng thái</button></form></div><?php admin_footer(); ?>
